export type PixelIconName = (typeof PIXEL_ICON_NAMES)[number];

export default function PixelIcon({
  name,
  size = 16,
  className = "",
  style,
  title,
}: {
  name: PixelIconName;
  /** Rendered size in px; multiples of 16 keep pixels crisp. */
  size?: number;
  className?: string;
  style?: CSSProperties;
  title?: string;
}) {
  return (
    <img
      src={`/pixel/icons/${name}.png`}
      alt={title ?? ""}
      aria-hidden={title ? undefined : true}
      title={title}
      width={size}
      height={size}
      draggable={false}
      className={`inline-block shrink-0 align-[-0.2em] ${className}`}
      style={{ imageRendering: "pixelated", ...style }}
    />
  );
}
